#[derive(Debug, Clone, Copy)]
pub struct Token {
    pub kind: TokenKind,
    span: Span,
}
impl Token {
    pub fn as_parse_tree<'a>(&self) -> ParseTree<'a> {
        ParseTree::Token(*self)
    }
    pub fn span(&self) -> Span {
        self.span
    }
}
fn token_kind(terminal_id: TerminalId) -> TokenKind {
    match terminal_id {
        // Cond
        TerminalId(0) => TokenKind::T0,
        // Id
        TerminalId(1) => TokenKind::T1,
        // Else
        TerminalId(2) => TokenKind::T2,
        // Letter
        TerminalId(3) => TokenKind::T3,
        // WhiteSpace
        TerminalId(4) => TokenKind::T4,
        // Comment
        TerminalId(5) => TokenKind::T5,
        // "if"
        TerminalId(6) => TokenKind::T6,
        // "("
        TerminalId(7) => TokenKind::T7,
        // ")"
        TerminalId(8) => TokenKind::T8,
        // ";"
        TerminalId(9) => TokenKind::T9,
        _ => unreachable!("Unknown TerminalId: {:?}", terminal_id),
    }
}
pub struct DanglingElseParseTreeBuilder<'a> {
    pub arena: &'a Arena,
}
impl<'a> DanglingElseParseTreeBuilder<'a> {
    pub fn new(tree_arena: &'a Arena) -> Self {
        Self { arena: tree_arena }
    }
}
impl<'a> ParseTreeBuilder<ParseTree<'a>> for DanglingElseParseTreeBuilder<'a> {
    fn new_nonterminal_node(
        &self,
        nonterminal_node: &NonterminalNode,
        children: &[ParseTree<'a>],
    ) -> ParseTree<'a> {
        match nonterminal_node.return_slot {
            // S = Statement+
            SlotId(1) => {
                let &[statements] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::S(self.arena.alloc(S::Alt0 {
                    statements: statements.unwrap_plus_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Statement = "if" Layout "(" Layout Cond Layout ")" Layout Statement #If
            SlotId(11) => {
                let &[
                    lit_0,
                    layout_1,
                    lit_2,
                    layout_3,
                    cond,
                    layout_5,
                    lit_6,
                    layout_7,
                    statement,
                ] = children
                else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Statement(self.arena.alloc(Statement::If {
                    lit_0: lit_0.unwrap_token(),
                    layout_1: layout_1.unwrap_layout(),
                    lit_2: lit_2.unwrap_token(),
                    layout_3: layout_3.unwrap_layout(),
                    cond: cond.unwrap_token(),
                    layout_5: layout_5.unwrap_layout(),
                    lit_6: lit_6.unwrap_token(),
                    layout_7: layout_7.unwrap_layout(),
                    statement: statement.unwrap_statement(),
                    span: nonterminal_node.span,
                }))
            }
            // Statement = "if" Layout "(" Layout Cond Layout ")" Layout Statement Layout Else Layout
            // Statement #IfElse
            SlotId(25) => {
                let &[
                    lit_0,
                    layout_1,
                    lit_2,
                    layout_3,
                    cond,
                    layout_5,
                    lit_6,
                    layout_7,
                    statement_8,
                    layout_9,
                    r#else,
                    layout_11,
                    statement_12,
                ] = children
                else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Statement(self.arena.alloc(Statement::IfElse {
                    lit_0: lit_0.unwrap_token(),
                    layout_1: layout_1.unwrap_layout(),
                    lit_2: lit_2.unwrap_token(),
                    layout_3: layout_3.unwrap_layout(),
                    cond: cond.unwrap_token(),
                    layout_5: layout_5.unwrap_layout(),
                    lit_6: lit_6.unwrap_token(),
                    layout_7: layout_7.unwrap_layout(),
                    statement_8: statement_8.unwrap_statement(),
                    layout_9: layout_9.unwrap_layout(),
                    r#else: r#else.unwrap_token(),
                    layout_11: layout_11.unwrap_layout(),
                    statement_12: statement_12.unwrap_statement(),
                    span: nonterminal_node.span,
                }))
            }
            // Statement = Id Layout ";" #Simple
            SlotId(29) => {
                let &[id, layout, lit_2] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Statement(self.arena.alloc(Statement::Simple {
                    id: id.unwrap_token(),
                    layout: layout.unwrap_layout(),
                    lit_2: lit_2.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Layout = (WhiteSpace | Comment)*
            SlotId(31) => {
                let &[star_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Layout(self.arena.alloc(Layout::Alt0 {
                    star_0: star_0.unwrap_star_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_0 = Statement+ Layout Statement
            SlotId(35) => {
                let &[statements_0, layout, statement_2] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus0(self.arena.alloc(Plus0::Alt0 {
                    statements_0: statements_0.unwrap_plus_0(),
                    layout: layout.unwrap_layout(),
                    statement_2: statement_2.unwrap_statement(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_0 = Statement
            SlotId(37) => {
                let &[statement] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus0(self.arena.alloc(Plus0::Alt1 {
                    statement: statement.unwrap_statement(),
                    span: nonterminal_node.span,
                }))
            }
            // Alt_0 = WhiteSpace
            SlotId(39) => {
                let &[white_space] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt0(self.arena.alloc(Alt0::Alt0 {
                    white_space: white_space.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Alt_0 = Comment
            SlotId(41) => {
                let &[comment] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Alt0(self.arena.alloc(Alt0::Alt1 {
                    comment: comment.unwrap_token(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_1 = (WhiteSpace | Comment)+ (WhiteSpace | Comment)
            SlotId(44) => {
                let &[plus_1, alt_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus1(self.arena.alloc(Plus1::Alt0 {
                    plus_1: plus_1.unwrap_plus_1(),
                    alt_0: alt_0.unwrap_alt_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Plus_1 = (WhiteSpace | Comment)
            SlotId(46) => {
                let &[alt_0] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Plus1(self.arena.alloc(Plus1::Alt1 {
                    alt_0: alt_0.unwrap_alt_0(),
                    span: nonterminal_node.span,
                }))
            }
            // Star_0 = (WhiteSpace | Comment)+
            SlotId(48) => {
                let &[plus_1] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star0(self.arena.alloc(Star0::Alt0 {
                    plus_1: plus_1.unwrap_plus_1(),
                    span: nonterminal_node.span,
                }))
            }
            // Star_0 =
            SlotId(49) => {
                let &[] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::Star0(self.arena.alloc(Star0::Alt1 {
                    span: nonterminal_node.span,
                }))
            }
            // StartS = Layout start:S Layout
            SlotId(53) => {
                let &[layout_0, start, layout_2] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::StartS(self.arena.alloc(Start {
                    before: layout_0.unwrap_layout(),
                    node: start.unwrap_s(),
                    after: layout_2.unwrap_layout(),
                    span: nonterminal_node.span,
                }))
            }
            // StartStatement = Layout start:Statement Layout
            SlotId(57) => {
                let &[layout_0, start, layout_2] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::StartStatement(self.arena.alloc(Start {
                    before: layout_0.unwrap_layout(),
                    node: start.unwrap_statement(),
                    after: layout_2.unwrap_layout(),
                    span: nonterminal_node.span,
                }))
            }
            // StartLayout = start:Layout
            SlotId(59) => {
                let &[start] = children else {
                    ParseTree::unexpected_node()
                };
                ParseTree::StartLayout(self.arena.alloc(Start {
                    before: (),
                    node: start.unwrap_layout(),
                    after: (),
                    span: nonterminal_node.span,
                }))
            }
            _ => unreachable!(),
        }
    }
    fn new_token(&self, terminal_node: &TerminalNode) -> ParseTree<'a> {
        ParseTree::Token(Token {
            kind: token_kind(terminal_node.terminal_id),
            span: terminal_node.span,
        })
    }
    fn new_ambiguity_node(
        &self,
        parent: NonterminalId,
        alternatives: Vec<ParseTree<'a>>,
    ) -> ParseTree<'a> {
        match parent {
            grammar::S => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_s()));
                ParseTree::S(self.arena.alloc(S::Amb(slice)))
            }
            grammar::STATEMENT => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_statement()));
                ParseTree::Statement(self.arena.alloc(Statement::Amb(slice)))
            }
            grammar::LAYOUT => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_layout()));
                ParseTree::Layout(self.arena.alloc(Layout::Amb(slice)))
            }
            grammar::PLUS_0 => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_plus_0()));
                ParseTree::Plus0(self.arena.alloc(Plus0::Amb(slice)))
            }
            grammar::ALT_0 => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_alt_0()));
                ParseTree::Alt0(self.arena.alloc(Alt0::Amb(slice)))
            }
            grammar::PLUS_1 => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_plus_1()));
                ParseTree::Plus1(self.arena.alloc(Plus1::Amb(slice)))
            }
            grammar::STAR_0 => {
                let slice = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_star_0()));
                ParseTree::Star0(self.arena.alloc(Star0::Amb(slice)))
            }
            grammar::START_S => {
                let first = alternatives[0].unwrap_start_s();
                let inner = self
                    .arena
                    .alloc_slice(alternatives.into_iter().map(|a| a.unwrap_start_s().node));
                let node = &*self.arena.alloc(S::Amb(inner));
                ParseTree::StartS(self.arena.alloc(Start {
                    before: first.before,
                    node,
                    after: first.after,
                    span: first.span,
                }))
            }
            grammar::START_STATEMENT => {
                let first = alternatives[0].unwrap_start_statement();
                let inner = self.arena.alloc_slice(
                    alternatives
                        .into_iter()
                        .map(|a| a.unwrap_start_statement().node),
                );
                let node = &*self.arena.alloc(Statement::Amb(inner));
                ParseTree::StartStatement(self.arena.alloc(Start {
                    before: first.before,
                    node,
                    after: first.after,
                    span: first.span,
                }))
            }
            grammar::START_LAYOUT => {
                let first = alternatives[0].unwrap_start_layout();
                let inner = self.arena.alloc_slice(
                    alternatives
                        .into_iter()
                        .map(|a| a.unwrap_start_layout().node),
                );
                let node = &*self.arena.alloc(Layout::Amb(inner));
                ParseTree::StartLayout(self.arena.alloc(Start {
                    before: first.before,
                    node,
                    after: first.after,
                    span: first.span,
                }))
            }
            _ => unreachable!("nonterminal cannot be ambiguous"),
        }
    }
}
// The parse tree of a finished parse, from the nonterminal node that spans the input.
pub fn create_parse_tree<'a>(
    root_id: SPPFNodeId,
    parser: &DanglingElseParser,
    builder: &DanglingElseParseTreeBuilder<'a>,
) -> ParseTree<'a> {
    let iguana_runtime::sppf::SPPFNode::Nonterminal(root) =
        iguana_runtime::parser::Parser::sppf_node(parser, root_id)
    else {
        panic!("the SPPF root is not a nonterminal node")
    };
    match root.nonterminal_id {
        grammar::S => ParseTree::S(visit_sppf(root_id, parser, builder).unwrap_s()),
        grammar::STATEMENT => {
            ParseTree::Statement(visit_sppf(root_id, parser, builder).unwrap_statement())
        }
        grammar::LAYOUT => ParseTree::Layout(visit_sppf(root_id, parser, builder).unwrap_layout()),
        grammar::PLUS_0 => ParseTree::Plus0(visit_sppf(root_id, parser, builder).unwrap_plus_0()),
        grammar::ALT_0 => ParseTree::Alt0(visit_sppf(root_id, parser, builder).unwrap_alt_0()),
        grammar::PLUS_1 => ParseTree::Plus1(visit_sppf(root_id, parser, builder).unwrap_plus_1()),
        grammar::STAR_0 => ParseTree::Star0(visit_sppf(root_id, parser, builder).unwrap_star_0()),
        grammar::START_S => {
            ParseTree::StartS(visit_sppf(root_id, parser, builder).unwrap_start_s())
        }
        grammar::START_STATEMENT => {
            ParseTree::StartStatement(visit_sppf(root_id, parser, builder).unwrap_start_statement())
        }
        grammar::START_LAYOUT => {
            ParseTree::StartLayout(visit_sppf(root_id, parser, builder).unwrap_start_layout())
        }
        _ => panic!(),
    }
}
impl<'a> ParseTreeNode for ParseTree<'a> {
    fn child(&self, index: usize) -> Option<Self> {
        ParseTree::child(self, index)
    }
    fn child_count(&self) -> usize {
        ParseTree::child_count(self)
    }
    fn display_name(&self) -> &'static str {
        ParseTree::display_name(self)
    }
    fn span(&self) -> Span {
        ParseTree::span(self)
    }
    fn kind(&self) -> NodeKind {
        if self.is_amb() {
            NodeKind::Amb
        } else if matches!(self, ParseTree::Token(_)) {
            NodeKind::Token
        } else {
            NodeKind::Nonterminal
        }
    }
    fn node_id(&self) -> Option<usize> {
        ParseTree::node_id(self)
    }
    fn origin(&self) -> Option<Origin> {
        ParseTree::origin(self)
    }
}
